<?php use Luna\Core\Csrf; use Luna\Core\View; ?>
<div class="page-actions"><a class="button" href="/documents/<?= View::e($type) ?>">← Elenco</a><div><a class="button" href="/documents/<?= View::e($type) ?>/<?= (int) $document['id'] ?>/pdf">PDF</a><?php if (in_array($definition['code'], ['SALES_INVOICE','CREDIT_NOTE'], true)): ?> <a class="button" href="/documents/<?= View::e($type) ?>/<?= (int) $document['id'] ?>/xml">XML FatturaPA</a><?php endif; ?></div></div>
<section class="card document-head"><div><span class="eyebrow"><?= View::e($definition['singular']) ?></span><h1><?= View::e($document['number']) ?></h1><p><?= View::e($document['counterparty_name']) ?> · <?= View::date($document['document_date']) ?></p></div><div class="document-total"><span>Totale</span><strong><?= View::money($document['total']) ?></strong><span class="badge"><?= View::e($document['status']) ?></span></div></section>
<section class="card table-wrap"><table><thead><tr><th>#</th><th>Descrizione</th><th>Q.tà</th><th>Prezzo</th><th>Sconto</th><th>Imponibile</th><th>IVA</th><th>Totale</th></tr></thead><tbody><?php foreach ($lines as $line): ?><tr><td><?= (int) $line['line_number'] ?></td><td><?= View::e($line['description']) ?></td><td><?= View::e($line['quantity'] . ' ' . $line['unit']) ?></td><td><?= View::money($line['unit_price']) ?></td><td><?= View::e($line['discount_percent']) ?>%</td><td><?= View::money($line['taxable_amount']) ?></td><td><?= View::e($line['vat_rate']) ?>%</td><td><?= View::money($line['total_amount']) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><td colspan="5"></td><th>Imponibile</th><td colspan="2"><?= View::money($document['taxable_total']) ?></td></tr><tr><td colspan="5"></td><th>IVA</th><td colspan="2"><?= View::money($document['vat_total']) ?></td></tr><tr><td colspan="5"></td><th>Totale</th><td colspan="2"><strong><?= View::money($document['total']) ?></strong></td></tr></tfoot></table></section>
